SELECT * FROM safety_incident
WHERE status <> 'ARCHIVED'
AND industry_code = #{industryCode}
AND incident_type = #{incidentType}
AND severity = #{severity}
ORDER BY occurred_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

